import { useEffect, useState } from 'react';
import Loading from '../../components/common/Loading';
import OrdersTable from '../../components/vendor/OrdersTable';
import { getErrorMessage, vendorAPI } from '../../services/api';
export default function Orders(){const[status,setStatus]=useState('');const[orders,setOrders]=useState([]);const[loading,setLoading]=useState(true);const[error,setError]=useState('');useEffect(()=>{setLoading(true);vendorAPI.getOrders(status?{status}:{}).then(({data})=>{setOrders(data.data);setError('');}).catch((e)=>setError(getErrorMessage(e))).finally(()=>setLoading(false));},[status]);const update=(id,nextStatus)=>setOrders((list)=>list.map((o)=>o.order_id===id?{...o,status:nextStatus}:o));return <div><h1 className="page-title">Orders</h1><p className="mt-1 text-sm text-slate-500">Progress marketplace orders through fulfillment.</p><div className="mt-6 flex flex-wrap gap-2">{[['','All'],['pending','Pending'],['processing','Processing'],['shipped','Shipped'],['delivered','Delivered']].map(([v,l])=><button key={l} onClick={()=>setStatus(v)} className={`rounded-full px-4 py-2 text-sm font-semibold ${status===v?'bg-violet-600 text-white':'border border-slate-200 bg-white text-slate-600'}`}>{l}</button>)}</div>{error&&<p className="mt-4 text-sm text-red-600">{error}</p>}<div className="mt-5">{loading?<Loading/>:<OrdersTable orders={orders} onUpdateStatus={update}/>}</div></div>}
